        '    <div class="ws-mm-stat" data-mm-stat="waiting"><div class="ws-mm-stat-label" data-mm="waiting-label">Queue</div><div class="ws-mm-stat-value-row"><span class="ws-mm-stat-icon" data-mm="waiting-icon" aria-hidden="true">☰</span><div class="ws-mm-stat-value" data-mm="open-lobbies">0</div></div></div>',
        '    <div class="ws-mm-stat" data-mm-stat="level"><div class="ws-mm-stat-label">Your Level</div><div class="ws-mm-stat-value-row"><span class="ws-mm-stat-icon" aria-hidden="true">▥</span><div class="ws-mm-stat-value" data-mm="level">LV 1</div></div></div>',
        '    <div class="ws-mm-stat" data-mm-stat="world" data-mm="world-stat-card"><div class="ws-mm-stat-label">World</div><div class="ws-mm-stat-value-row"><span class="ws-mm-stat-icon" aria-hidden="true">◇</span><div class="ws-mm-stat-value" data-mm="world-stat">WORLD 1</div></div></div>',
        '  </div>',
