        shareCodeRow: modal.querySelector('[data-mm="share-code-row"]'),
        nearbyCode: modal.querySelector('[data-mm="nearby-code"]'),
        inviteWrap: modal.querySelector('[data-mm="invite-wrap"]'),
        inviteQrCode: modal.querySelector('[data-mm="invite-qr-code"]'),
        inviteRaw: modal.querySelector('[data-mm="invite-raw"]'),
