    // Synthesized Web Audio sounds — no asset files required
    const wsAudio = (() => {
      let ctx = null;
      const getCtx = () => {
        if (!ctx || ctx.state === 'closed') ctx = new (window.AudioContext || window.webkitAudioContext)();
        if (ctx.state === 'suspended') ctx.resume();
        return ctx;
      };
      const out = (node, delay, duration) => {
        node.connect(getCtx().destination);
        node.start(getCtx().currentTime + (delay || 0));
        node.stop(getCtx().currentTime + (delay || 0) + duration);
      };
      const osc = (type, freq, gainVal, delay, dur, freqEnd, gainEnd) => {
        const c = getCtx(), o = c.createOscillator(), g = c.createGain();
        o.type = type; o.connect(g); g.connect(c.destination);
        o.frequency.setValueAtTime(freq, c.currentTime + (delay||0));
        if (freqEnd) o.frequency.exponentialRampToValueAtTime(freqEnd, c.currentTime + (delay||0) + dur);
        g.gain.setValueAtTime(gainVal, c.currentTime + (delay||0));
        g.gain.exponentialRampToValueAtTime(gainEnd || 0.001, c.currentTime + (delay||0) + dur);
        o.start(c.currentTime + (delay||0));
        o.stop(c.currentTime + (delay||0) + dur);
      };
      return {
        hover() {
          try { osc('sine', 900, 0.07, 0, 0.055, 500, 0.001); } catch(e){}
        },
        select(colorKey) {
          try {
            const c = getCtx();
            // Layer 1 — low impact thump
            osc('sawtooth', 130, 0.45, 0,    0.14, 35,   0.001);
            // Layer 2 — rising mid sweep
            osc('sine',     380, 0.22, 0.04, 0.55, 1400, 0.001);
            // Layer 3 — high confirmation ping
            osc('sine',    2000, 0.13, 0.12, 0.75, 2800, 0.001);
            // Layer 4 — noise burst (attack card variant adds extra crunch)
            if (colorKey === 'attack') osc('sawtooth', 80, 0.3, 0, 0.08, 25, 0.001);
          } catch(e){}
        },
        entrance() {
          try {
            // Staggered card power-on beeps matching the stagger animation
            [0.1, 0.28, 0.46].forEach((delay, i) => {
              osc('sine', 600 + i * 200, 0.09, delay, 0.18, 1000 + i * 300, 0.001);
            });
          } catch(e){}
        }
      };
    })();

